import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {
    private static Map<Long, Long> cache = new HashMap<>();

    public static long solve(long n) {
        if (cache.containsKey(n)) {
            return cache.get(n);
        }
        if (n <= 11) {
            long result = Math.min(n, 2 + (11 - n));
            cache.put(n, result);
            return result;
        }
        long val = 1;
        long count = 1;
        while (val <= n) {
            val = val * 10 + 1;
            count++;
        }
        long limit = val / 10;
        long res;
        if (val > 2 * n) {
            long quotient = n / limit;
            long rem = n % limit;
            long res1 = solve(val - n) + count;
            long res2 = quotient * (count - 1) + solve(rem);
            res = Math.min(res1, res2);
        } else {
            long quotient = n / limit;
            long rem = n % limit;
            long res1 = solve(val - n) + count;
            long res2 = quotient * (count - 1) + solve(rem);
            res = Math.min(res1, res2);
        }
        cache.put(n, res);
        return res;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long input = scanner.nextLong();
        System.out.println(solve(input));
        scanner.close();
    }
}
